def build():
    s = SRC.read_text(encoding="utf-8")
    for en, ro in sorted(PAIRS, key=lambda p: -len(p[0])):
        s = s.replace(en, ro)
    return s


def main():
    out = build()
    DST.write_text(out, encoding="utf-8")
    print(f"wrote {DST.relative_to(ROOT)} ({len(out)} bytes)")


if __name__ == "__main__":
    main()
